 "content": "def transform(grid):
    """Extend a solid color-2 rectangle along unobstructed row/column rays."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    out = [row[:] for row in grid]
    # Preserve the source rectangle and extend its rows in either clear direction.
    for r in range(r0, r1 + 1):
        if all(grid[r][c] in (0, 2) for c in range(0, c0)):
            for c in range(c0):
                out[r][c] = 2
        if all(grid[r][c] in (0, 2) for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2
    # Extend the source columns vertically when that entire ray has no marker.
    for c in range(c0, c1 + 1):
        if all(grid[r][c] in (0, 2) for r in range(0, r0)):
            for r in range(r0):
                out[r][c] = 2
        if all(grid[r][c] in (0, 2) for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
